-- Enlaces editoriales en español para audiencia latinoamericana.
update public.site_content set value=jsonb_set(value,'{articles}',(
 select jsonb_agg(article || jsonb_build_object(
  'source',case article->>'id' when 'adolescencia-identidad' then 'Organización Mundial de la Salud en español' when 'primer-desamor' then 'UNICEF en español' when 'amistades-limites' then 'UNICEF en español' when 'presion-estudios' then 'Organización Mundial de la Salud en español' when 'sueno-aprendizaje' then 'MedlinePlus en español' when 'redes-comparacion' then 'UNICEF en español' when 'elegir-carrera' then 'Mi Próximo Paso · Departamento de Trabajo de EE. UU.' when 'ansiedad-pedir-ayuda' then 'MedlinePlus en español' when 'fortalezas' then 'UNICEF en español' when 'neurodiversidad' then 'Organización Mundial de la Salud en español' when 'tdah-contexto' then 'MedlinePlus en español' else 'UNICEF en español' end,
  'url',case article->>'id' when 'adolescencia-identidad' then 'https://www.who.int/es/news-room/fact-sheets/detail/adolescent-mental-health' when 'primer-desamor' then 'https://www.unicef.org/parenting/es/salud-mental/temas-salud-mental-14-18' when 'amistades-limites' then 'https://www.unicef.org/parenting/es/salud-mental-bienestar' when 'presion-estudios' then 'https://www.who.int/es/news-room/fact-sheets/detail/adolescent-mental-health' when 'sueno-aprendizaje' then 'https://medlineplus.gov/spanish/healthysleep.html' when 'redes-comparacion' then 'https://www.unicef.org/parenting/es/salud-mental-bienestar' when 'elegir-carrera' then 'https://www.miproximopaso.org/find/interests' when 'ansiedad-pedir-ayuda' then 'https://medlineplus.gov/spanish/mentalhealth.html' when 'fortalezas' then 'https://www.unicef.org/parenting/es/salud-mental-bienestar' when 'neurodiversidad' then 'https://www.who.int/es/news-room/fact-sheets/detail/autism-spectrum-disorders' when 'tdah-contexto' then 'https://medlineplus.gov/spanish/attentiondeficithyperactivitydisorder.html' else 'https://www.unicef.org/parenting/es/salud-mental/temas-salud-mental-14-18' end,
  'link_label','Leer contenido en español')) from jsonb_array_elements(value->'articles') article
)),updated_at=now() where key='news';
